// UnitySynchronizationContext, если упростить
public override void Post(SendOrPostCallback cb, object state)
{
    lock (_queue) _queue.Add((cb, state));          // из любого потока
}

void ExecuteTasks()                                 // player loop зовёт раз за кадр
{
    lock (_queue) { _batch.AddRange(_queue); _queue.Clear(); }
    foreach (var (cb, state) in _batch) cb(state);  // на главном потоке
    _batch.Clear();
}

