async Awaitable FlyAsync()
{
    await Awaitable.BackgroundThreadAsync();  // 1. дальше — поток пула
    var path = FindPath(map);                 // 2. тяжёлый расчёт, кадры идут
    await Awaitable.MainThreadAsync();        // 3. обратно на главный поток
    for (int i = 0; i < path.Length; i++)
    {
        transform.position = path[i];         // 4. Unity API — можно
        await Awaitable.NextFrameAsync();     // 5. по точке за кадр
    }
}

